categories.formula:
(_c, report, folderStatus) => {
      const value = get(report, 'output.statusCode');
      if (value === null || value === undefined || value === '') return folderStatus === 'success' ? '200' : 'ثبت نشده';
      return String(value) === '200' ? '200' : String(value);
    }

